style:
.tw-zitang.resume-paper {
  color: #2b2636;
}

.tw-zitang.resume-paper .paper-header {
  position: relative;
  display: block;
  margin: 0 0 6.5mm;
  padding: 0 0 4.5mm;
  border: none;
  border-bottom: 1px solid #ebe5f4;
}

.tw-zitang.resume-paper .paper-header::before {
  content: "";
  position: absolute;
  top: calc(var(--paper-mt, 15mm) * -1);
  left: calc(var(--paper-ml, 15mm) * -1);
  right: calc(var(--paper-mr, 15mm) * -1);
  height: 2.2mm;
  background: linear-gradient(90deg, #6d4fa1 0%, #9b82c8 58%, #c0aede 100%);
  print-color-adjust: exact;
}

.tw-zitang.resume-paper .paper-header__main {
  padding-right: 34mm;
}

.tw-zitang.resume-paper .paper-photo {
  position: absolute;
  top: 0;
  right: 0;
  width: 27mm;
  height: 35mm;
  border: 0.5mm solid #e2d8f2;
  border-radius: 1mm;
  box-shadow: none;
  print-color-adjust: exact;
}

.tw-zitang.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #f4effa;
  color: #6d4fa1;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 600;
}

.tw-zitang.resume-paper .paper-name {
  color: #33254f;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.02);
  letter-spacing: 0.06em;
}

.tw-zitang.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #74668a;
}

.tw-zitang.resume-paper .paper-role {
  margin-top: 1.3mm;
  color: #6d4fa1;
  font-weight: 600;
}

.tw-zitang.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #8d81a1;
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-zitang.resume-paper .paper-contacts--labeled {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.3mm 8mm;
  margin-top: 3mm;
  padding-top: 2.8mm;
  border-top: 1px solid #f0eaf7;
  color: #3d3449;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-zitang.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-zitang.resume-paper .paper-contact__label {
  color: #877d96;
}

.tw-zitang.resume-paper .paper-section .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  padding: 1.4mm 3mm;
  background: #f0eaf8;
  border-radius: 1mm;
  color: #4b3573;
  font-size: calc(var(--paper-base-size) * 1);
  letter-spacing: 0.1em;
  print-color-adjust: exact;
}

.tw-zitang.resume-paper .paper-section .paper-section__icon {
  display: grid;
  place-items: center;
  width: 5mm;
  height: 5mm;
  border: none;
  border-radius: 50%;
  background: #6d4fa1;
  color: #fff;
}

.tw-zitang.resume-paper .paper-section .paper-section__icon svg {
  width: 58%;
  height: 58%;
}

.tw-zitang.resume-paper .paper-section .paper-section__title::after {
  content: none;
}

.tw-zitang.resume-paper .paper-section .paper-section__body {
  margin-top: 2.3mm;
  color: #332c3d;
}

.tw-zitang.resume-paper .paper-section .paper-item-title {
  color: #2c2140;
}

.tw-zitang.resume-paper .paper-section .paper-item-period {
  color: #6f6283;
  font-weight: 600;
}

.tw-zitang.resume-paper .paper-section .paper-item-sub {
  color: #4c435a;
}

.tw-zitang.resume-paper .paper-section .paper-note__tag {
  color: #6d4fa1;
}

.tw-zitang.resume-paper .paper-section .paper-skill {
  border-bottom-color: #ece6f4;
}

.tw-zitang.resume-paper .paper-section .paper-skill__level {
  color: #6d4fa1;
}

.tw-zitang.resume-paper .paper-footer {
  border-top: 1px solid #ebe5f4;
  color: #7b7089;
}
